<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getList, getPage, post } from '@/api/resources'
import { problemMessage } from '@/api/http'
import type { Asset, WorkOrder } from '@/types/domain'
import StatusTag from '@/components/StatusTag.vue'
import ProductionHint from '@/components/ProductionHint.vue'
import { formatDate } from '@/utils/format'

interface Worker { id: string; displayName: string; userName: string }
interface Template { type: string; name?: string; checklist?: string[] }
const orders = ref<WorkOrder[]>([]); const assets = ref<Asset[]>([]); const workers = ref<Worker[]>([]); const templates = ref<Template[]>([]); const loading = ref(true); const error = ref(''); const keyword = ref(''); const status = ref(''); const dialog = ref(false); const submitting = ref(false); const form = reactive({ title: '', type: 'Maintenance', assetId: '', eventId: '', assigneeId: '', dueAt: '', priority: 'Normal', details: '', checklist: [] as string[], maintenanceItem: '', repairFault: '', floodZone: '', plantCareItem: '', patrolRoute: '', cleaningArea: '', inspectionFinding: '' })
const detailPrompt = computed(() => ({ Maintenance: '保养项目与下次维护建议', Repair: '故障描述、处理方案或费用记录', Flood: '重点区域、防汛检查与预案关联', PlantCare: '浇水、修剪、施肥或病虫处理项目', Patrol: '巡更区域、路线与异常说明', Cleaning: '保洁区域、任务项目与完成说明', Inspection: '检查表、发现问题与整改要求' }[form.type] || '处置说明'))
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const [orderData, assetData, workerData, templateData] = await Promise.all([getPage<WorkOrder>('/operations/work-orders', { status: status.value || undefined }), getPage<Asset>('/assets', { pageSize: 100 }), getPage<Worker>('/auth/workers', { pageSize: 100 }), getList<Template>('/operations/templates')]); orders.value = keyword.value.trim() ? orderData.items.filter((item) => `${item.number ?? ''} ${item.title}`.toLowerCase().includes(keyword.value.trim().toLowerCase())) : orderData.items; assets.value = assetData.items; workers.value = workerData.items; templates.value = templateData } catch (e) { error.value = problemMessage(e) } finally { loading.value = false } }
function openCreate(): void { Object.assign(form, { title: '', type: 'Maintenance', assetId: '', eventId: '', assigneeId: '', dueAt: '', priority: 'Normal', details: '', checklist: [], maintenanceItem: '', repairFault: '', floodZone: '', plantCareItem: '', patrolRoute: '', cleaningArea: '', inspectionFinding: '' }); dialog.value = true }
function useTemplate(): void { const found = templates.value.find((item) => item.type === form.type); form.checklist = [...(found?.checklist ?? [])] }
function typeDetails(): string { return JSON.stringify({ maintenanceItem: form.maintenanceItem, repairFault: form.repairFault, floodZone: form.floodZone, plantCareItem: form.plantCareItem, patrolRoute: form.patrolRoute, cleaningArea: form.cleaningArea, inspectionFinding: form.inspectionFinding, notes: form.details }) }
function assigneeName(assigneeId?: string): string { const worker = workers.value.find((item) => item.id === assigneeId); return worker?.displayName || worker?.userName || '未分派' }
async function create(): Promise<void> { if (!form.title || !form.assigneeId || !form.dueAt) return ElMessage.warning('请填写标题、处理人和截止时间。'); submitting.value = true; try { await post('/operations/work-orders', { title: form.title, type: form.type, assetId: form.assetId || undefined, eventId: form.eventId || undefined, assigneeId: form.assigneeId, dueAt: form.dueAt, priority: form.priority, detailsJson: typeDetails(), checklist: form.checklist.filter(Boolean) }); dialog.value = false; await load(); ElMessage.success('工单已创建并分派。') } catch (e) { ElMessage.error(problemMessage(e)) } finally { submitting.value = false } }
onMounted(() => { void load() })
</script>
<template><div class="page"><div class="page-heading"><div><h1>智慧运维</h1><p>按七类业务工单组织分派、反馈和验收；不含移动定位、打卡或相机采集。</p></div><el-button type="primary" @click="openCreate">创建并分派工单</el-button></div><section class="surface toolbar"><el-input v-model="keyword" placeholder="搜索工单编号、标题" clearable @keyup.enter="load" /><el-select v-model="status" clearable placeholder="状态" @change="load"><el-option v-for="item in ['Assigned','Accepted','InProgress','PendingReview','Completed','Cancelled']" :key="item" :value="item" /></el-select><el-button @click="load">查询</el-button><span class="toolbar-note">作业人员只能在“我的任务”中操作分配给自己的工单。</span></section><el-alert v-if="error" type="error" :title="error" :closable="false" /><section class="surface table-panel" v-loading="loading"><el-table :data="orders" empty-text="暂无工单"><el-table-column prop="number" label="编号" width="140" /><el-table-column prop="title" label="工单内容" min-width="210" /><el-table-column prop="type" label="类型" width="120" /><el-table-column prop="priority" label="优先级" width="100" /><el-table-column label="处理人" width="120"><template #default="scope">{{ assigneeName(scope.row.assigneeId) }}</template></el-table-column><el-table-column label="截止时间" width="180"><template #default="scope">{{ formatDate(scope.row.dueAt) }}</template></el-table-column><el-table-column label="状态" width="130"><template #default="scope"><StatusTag :status="scope.row.status" /></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="scope"><el-button link type="primary" @click="$router.push(`/admin/operations/work-orders/${scope.row.id}`)">查看处置</el-button></template></el-table-column></el-table></section><section class="surface flood-panel"><div><b>防汛防台预案</b><p>预案以公园区域和检查项目为主体，可关联防汛类型工单。</p></div><el-button @click="$router.push('/admin/emergency')">查看应急事件与预案</el-button></section><ProductionHint topic="desktop" /><el-dialog v-model="dialog" title="创建并分派工单" width="760px" :close-on-click-modal="false"><el-form label-position="top"><div class="form-row"><el-form-item label="工单标题" required><el-input v-model="form.title" /></el-form-item><el-form-item label="业务类型" required><el-select v-model="form.type" @change="useTemplate"><el-option v-for="item in ['Maintenance','Repair','Flood','PlantCare','Patrol','Cleaning','Inspection']" :key="item" :value="item" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="关联资产"><el-select v-model="form.assetId" clearable filterable><el-option v-for="item in assets" :key="item.id" :value="item.id" :label="`${item.code} · ${item.name}`" /></el-select></el-form-item><el-form-item label="处理人" required><el-select v-model="form.assigneeId" filterable><el-option v-for="item in workers" :key="item.id" :value="item.id" :label="item.displayName || item.userName" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="截止时间" required><el-date-picker v-model="form.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]" /></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option value="Low" /><el-option value="Normal" /><el-option value="High" /><el-option value="Urgent" /></el-select></el-form-item></div><el-form-item :label="detailPrompt"><el-input v-model="form.details" type="textarea" :rows="3" placeholder="填写类型专属的任务背景与处置要求" /></el-form-item><div v-if="form.type === 'Maintenance'" class="type-detail"><el-input v-model="form.maintenanceItem" placeholder="保养项目，例如：滤网清洁、阀门检查" /></div><div v-else-if="form.type === 'Repair'" class="type-detail"><el-input v-model="form.repairFault" placeholder="故障描述与建议维修方案" /></div><div v-else-if="form.type === 'Flood'" class="type-detail"><el-input v-model="form.floodZone" placeholder="重点区域与预案说明" /></div><div v-else-if="form.type === 'PlantCare'" class="type-detail"><el-input v-model="form.plantCareItem" placeholder="养护项目，例如修剪、浇水、施肥" /></div><div v-else-if="form.type === 'Patrol'" class="type-detail"><el-input v-model="form.patrolRoute" placeholder="巡更区域与路线说明（不含定位打卡）" /></div><div v-else-if="form.type === 'Cleaning'" class="type-detail"><el-input v-model="form.cleaningArea" placeholder="保洁区域与项目" /></div><div v-else class="type-detail"><el-input v-model="form.inspectionFinding" placeholder="检查表与问题整改要求" /></div><el-form-item label="检查清单"><div class="checklist-editor"><el-input v-for="(_item, index) in form.checklist" :key="index" v-model="form.checklist[index]" placeholder="检查项目" /><el-button @click="form.checklist.push('')">新增检查项</el-button></div></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="submitting" @click="create">创建并分派</el-button></template></el-dialog></div></template>
<style scoped>.toolbar-note { margin-left:auto; color:#74857f; font-size:12px; }.table-panel { padding:18px; margin-top:16px; }.flood-panel { margin-top:18px; padding:16px; display:flex; align-items:center; justify-content:space-between; }.flood-panel b { color:#314f47; }.flood-panel p { margin:5px 0 0; color:#72837d; font-size:12px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }.type-detail { padding:12px; margin:-6px 0 16px; border-left:3px solid #6cad92; background:#f4f8f5; }.checklist-editor { display:grid; gap:8px; width:100%; }</style>
